BEGIN;
DO $import$
DECLARE
  payload jsonb := $payload$[{"rank":1,"name":"Seth Low / Amos Tham","handle":"historical-2024-csc-29er-jan-2024-109d74984b68","sail":"SGP","club":"SAFYC","school":null,"gender":"M","nationality":null,"total":9,"nett":7,"duplicateName":false,"races":[[2,null,true],[1,null,false],[2,null,false],[1,null,false],[1,null,false],[1,null,false],[1,null,false]]},{"rank":2,"name":"Nicole Ng Hui Hong / Ezann Sephira Tan","handle":"historical-2024-csc-29er-jan-2024-7e2cc8a29898","sail":"SIN","club":"SAFYC","school":null,"gender":"F","nationality":null,"total":17,"nett":12,"duplicateName":false,"races":[[5,"DSQ",true],[2,null,false],[1,null,false],[3,null,false],[2,null,false],[2,null,false],[2,null,false]]},{"rank":3,"name":"Cheryl Yong Heng Xi / Annika Chui","handle":"historical-2024-csc-29er-jan-2024-3d455a6bbe00","sail":"8","club":"CSC","school":null,"gender":"F","nationality":null,"total":20,"nett":16,"duplicateName":false,"races":[[1,null,false],[3,null,false],[3,null,false],[2,null,false],[4,null,true],[3,null,false],[4,null,false]]},{"rank":4,"name":"Josh Ang Shaal","handle":"historical-2024-csc-29er-jan-2024-19a995d5ebbe","sail":"153","club":null,"school":null,"gender":"M","nationality":null,"total":27,"nett":22,"duplicateName":false,"races":[[5,"DNS",true],[4,null,false],[4,null,false],[4,null,false],[3,null,false],[4,null,false],[3,null,false]]}]$payload$::jsonb;
  v_event uuid;
  v_regatta uuid;
  v_sailor uuid;
  v_result uuid;
  v_candidate_count integer;
  v_expected_results integer := 4;
  v_expected_races integer := 7;
  item jsonb;
  race jsonb;
  race_no integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('official-2024-csc-29er-jan-2024'));
  SELECT id INTO v_event FROM public.regatta_events WHERE slug = 'csc-ilca-29er-championships-2024';
  IF v_event IS NULL THEN RAISE EXCEPTION 'Missing parent event: %', 'csc-ilca-29er-championships-2024'; END IF;

  INSERT INTO public.regattas (
    name, slug, event_id, date, end_date, total_fleet_size, division, race_count,
    geography, boat_class, counts_for_ranking, venue, organizer, schedule_notes, status, reviewed_at
  ) VALUES (
    'CSC ILCA & 29er Championships 2024 (29er)', 'csc-29er-jan-2024', v_event, DATE '2024-01-13', DATE '2024-01-14',
    4, 'Open', 7, 'SGP', '29er', false,
    'Changi Sailing Club, Singapore', 'Changi Sailing Club', 'Official provisional results, visually reviewed. Best 6 of 7 races count. Two-person boats are retained as historical team-entry profiles.', 'published', now()
  ) ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name, event_id = EXCLUDED.event_id, date = EXCLUDED.date, end_date = EXCLUDED.end_date,
    total_fleet_size = EXCLUDED.total_fleet_size, division = EXCLUDED.division, race_count = EXCLUDED.race_count,
    geography = EXCLUDED.geography, boat_class = EXCLUDED.boat_class, counts_for_ranking = EXCLUDED.counts_for_ranking,
    venue = EXCLUDED.venue, organizer = EXCLUDED.organizer, schedule_notes = EXCLUDED.schedule_notes,
    status = 'published', reviewed_at = now(), updated_at = now()
  RETURNING id INTO v_regatta;

  FOR item IN SELECT value FROM jsonb_array_elements(payload) LOOP
    SELECT count(DISTINCT s.id), min(s.id::text)::uuid INTO v_candidate_count, v_sailor
    FROM public.sailors s
    LEFT JOIN public.sailor_aliases a ON a.sailor_id = s.id
    WHERE (lower(trim(COALESCE(s.name, ''))) = lower(trim(item->>'name')) OR lower(trim(COALESCE(a.alias_name, ''))) = lower(trim(item->>'name')))
      AND (COALESCE((item->>'duplicateName')::boolean, false) = false OR (lower(trim(COALESCE(s.sail_number, ''))) = lower(trim(COALESCE(item->>'sail', ''))) OR lower(trim(COALESCE(s.sail_number_ilca4, ''))) = lower(trim(COALESCE(item->>'sail', '')))));

    IF v_candidate_count > 1 THEN
      RAISE EXCEPTION 'Ambiguous SailorPath identity for % (% candidates)', item->>'name', v_candidate_count;
    ELSIF v_candidate_count = 0 THEN
