      gender = EXCLUDED.gender, nationality = EXCLUDED.nationality, evidence_url = EXCLUDED.evidence_url,
      evidence_name = EXCLUDED.evidence_name, evidence_type = EXCLUDED.evidence_type, official_url = EXCLUDED.official_url,
      evidence_notes = EXCLUDED.evidence_notes, verification_status = 'verified', verified_at = now(), updated_at = now()
    RETURNING id INTO v_result;

    race_no := 0;
    FOR race IN SELECT value FROM jsonb_array_elements(item->'races') LOOP
      race_no := race_no + 1;
      INSERT INTO public.regatta_race_results (regatta_result_id, race_number, score, scoring_code, discarded, raw_value)
      VALUES (
        v_result, race_no, (race->>0)::real, race->>1, (race->>2)::boolean,
        CASE WHEN race->>1 IS NULL THEN CASE WHEN (race->>2)::boolean THEN '(' || (race->>0) || ')' ELSE race->>0 END
             ELSE CASE WHEN (race->>2)::boolean THEN '(' || (race->>1) || ',' || (race->>0) || ')' ELSE (race->>1) || ',' || (race->>0) END END
      ) ON CONFLICT (regatta_result_id, race_number) DO UPDATE SET
        score = EXCLUDED.score, scoring_code = EXCLUDED.scoring_code, discarded = EXCLUDED.discarded,
        raw_value = EXCLUDED.raw_value, updated_at = now();
    END LOOP;
    DELETE FROM public.regatta_race_results WHERE regatta_result_id = v_result AND race_number > race_no;

    IF race_no <> v_expected_races
       OR (SELECT sum(score) FROM public.regatta_race_results WHERE regatta_result_id = v_result) <> (item->>'total')::real
       OR (SELECT sum(score) FROM public.regatta_race_results WHERE regatta_result_id = v_result AND NOT discarded) <> (item->>'nett')::real THEN
      RAISE EXCEPTION 'Individual race-score validation failed for %', item->>'name';
    END IF;
  END LOOP;

  IF (SELECT count(*) FROM public.regatta_results WHERE regatta_id = v_regatta) <> v_expected_results THEN
    RAISE EXCEPTION 'Unexpected result count for csc-29er-jan-2024';
  END IF;
  IF (SELECT count(*) FROM public.regatta_race_results race JOIN public.regatta_results result ON result.id = race.regatta_result_id WHERE result.regatta_id = v_regatta) <> v_expected_results * v_expected_races THEN
    RAISE EXCEPTION 'Unexpected race-score count for csc-29er-jan-2024';
  END IF;
END
$import$;
COMMIT;

SELECT r.slug, count(DISTINCT rr.id)::int AS result_count, count(race.id)::int AS race_score_count,
       bool_and(rr.total_score = scores.total_score AND rr.nett_score = scores.nett_score) AS scores_reconcile
FROM public.regattas r
LEFT JOIN public.regatta_results rr ON rr.regatta_id = r.id
LEFT JOIN public.regatta_race_results race ON race.regatta_result_id = rr.id
LEFT JOIN LATERAL (
  SELECT sum(score)::real AS total_score, sum(score) FILTER (WHERE NOT discarded)::real AS nett_score
  FROM public.regatta_race_results
  WHERE regatta_result_id = rr.id
) scores ON true
WHERE r.slug = 'csc-29er-jan-2024'
GROUP BY r.slug
LIMIT 1;
